import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'

const noticeVariants = cva('p-3 rounded-lg border text-sm', {
  variants: {
    tone: {
      error: [
        'bg-[var(--color-error-50)] dark:bg-[color-mix(in_srgb,var(--color-error-900)_20%,transparent)]',
        'border-[var(--color-error-200)] dark:border-[var(--color-error-800)]',
        'text-[var(--color-error-700)] dark:text-[var(--color-error-400)]',
      ].join(' '),
      warning: [
        'bg-[var(--color-warning-50)] dark:bg-[color-mix(in_srgb,var(--color-warning-900)_20%,transparent)]',
        'border-[var(--color-warning-200)] dark:border-[var(--color-warning-800)]',
        'text-[var(--color-warning-700)] dark:text-[var(--color-warning-400)]',
      ].join(' '),
      success: [
        'bg-[var(--color-success-50)] dark:bg-[color-mix(in_srgb,var(--color-success-900)_20%,transparent)]',
        'border-[var(--color-success-200)] dark:border-[var(--color-success-800)]',
        'text-[var(--color-success-700)] dark:text-[var(--color-success-400)]',
      ].join(' '),
      info: [
        'bg-[var(--color-info-50)] dark:bg-[color-mix(in_srgb,var(--color-info-900)_20%,transparent)]',
        'border-[var(--color-info-200)] dark:border-[var(--color-info-800)]',
        'text-[var(--color-info-700)] dark:text-[var(--color-info-400)]',
      ].join(' '),
      neutral: [
        'bg-[var(--color-warm-50)] dark:bg-[var(--color-neutral-800)]',
        'border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
        'text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]',
      ].join(' '),
    },
  },
  defaultVariants: {
    tone: 'neutral',
  },
})

export interface NoticeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof noticeVariants> {
  /** Optional leading icon element (e.g. a 16px filled Phosphor icon),
   *  rendered in the tone's text color on the same line as the content. */
  icon?: React.ReactNode
}

/**
 * In-flow, tone-tinted status box for context-bound messages: sync results,
 * form validation errors, inline confirmations. Sits in the surrounding
 * layout (inside Settings sections, below form fields) rather than floating.
 * For app-level floating notifications below the header, use `Toast`.
 *
 * With `icon`, the content renders on one line next to it. Without `icon`,
 * children render as-is, so richer layouts (multiple lines, button rows)
 * can be passed directly.
 */
/** Maps a tone to its ARIA live-region role and aria-live value. */
function getToneAriaProps(tone: string | null | undefined): React.HTMLAttributes<HTMLDivElement> {
  switch (tone) {
    case 'error':
      return { role: 'alert' }
    case 'success':
    case 'warning':
    case 'info':
      return { role: 'status', 'aria-live': 'polite' }
    default:
      // 'neutral' and undefined: plain div, no live-region semantics
      return {}
  }
}

const Notice = React.forwardRef<HTMLDivElement, NoticeProps>(
  ({ tone, icon, className, children, ...props }, ref) => {
    const ariaProps = getToneAriaProps(tone)
    return (
      <div ref={ref} className={cn(noticeVariants({ tone }), className)} {...ariaProps} {...props}>
        {icon ? (
          <p className="flex items-center gap-2">
            {icon}
            <span className="min-w-0">{children}</span>
          </p>
        ) : (
          children
        )}
      </div>
    )
  },
)
Notice.displayName = 'Notice'

export { Notice, noticeVariants }
